const suggestUsername = (name) => {
  const ascii = name.toLowerCase().replace(/[^a-z0-9\s]/g, '').trim().split(/\s+/).filter(Boolean).join('.');
  if (ascii.length >= 3) return ascii.slice(0, 30);
  return `student${Math.floor(1000 + Math.random() * 9000)}`;
};

setForm((f) => {
